def hill_equation(emax, concentration, ec50, hill_n):
    if concentration <= 0.0 or ec50 <= 0.0:
        return 0.0
    cn = (concentration) ** (hill_n)
    ec50n = (ec50) ** (hill_n)
    return emax * cn / (ec50n + cn)



def therapeutic_index(td50, ed50):
    if ed50 <= 0.0:
        return 0.0
    return td50 / ed50



def drug_bioavailability(auc_oral, auc_iv, dose_oral, dose_iv):
    if auc_iv <= 0.0 or dose_oral <= 0.0:
        return 0.0
    return (auc_oral / auc_iv) * (dose_iv / dose_oral)



def receptor_occupancy(drug_conc, kd):
    denom = kd + drug_conc
    if denom <= 0.0:
        return 0.0
    return drug_conc / denom



def drug_protein_binding(bound_fraction):
    if bound_fraction < 0.0 or bound_fraction > 1.0:
        return 1.0
    return 1.0 - bound_fraction



def volume_of_distribution(dose, c_plasma_zero):
    if c_plasma_zero <= 0.0:
        return 0.0
    return dose / c_plasma_zero



def clearance_from_halflife(volume_of_dist, half_life):
    if half_life <= 0.0:
        return 0.0
    return 0.693 * volume_of_dist / half_life



def steady_state_concentration(bioavailability, dose, clearance, tau):
    denom = clearance * tau
    if denom <= 0.0:
        return 0.0
    return bioavailability * dose / denom



def loading_dose(volume_of_dist, target_conc):
    return volume_of_dist * target_conc



def drug_interaction_index(dose_a, dm_a, dose_b, dm_b):
    if dm_a <= 0.0 or dm_b <= 0.0:
        return 0.0
    return dose_a / dm_a + dose_b / dm_b
